            var os       = require('os');
            var dns      = require('dns');
            var util     = require('util');
            var host = ( typeof(hostname) !== 'undefined' && hostname !== '' ) ? hostname : os.hostname();
            if ( /\./.test(host) ) return host;
            var ipObj = await util.promisify(dns.lookup)(host, { hints: dns.ADDRCONFIG || dns.V4MAPPED });
