            if ( $el && $el.__ginaOnKeydown ) {
                $el.removeEventListener('keydown', $el.__ginaOnKeydown);
                $el.__ginaOnKeydown = null;
            }
            var $inert = document.querySelectorAll('[data-gina-popin-inert]');
